public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the notification settings of a chat. Notification settings of a chat with the current user (Saved Messages) can't be changed
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetChatNotificationSettingsAsync(long chatId = default, ChatNotificationSettings notificationSettings = default)
    {

           using var activity =  StartCallActivity("SetChatNotificationSettingsAsync", typeof(SetChatNotificationSettings).FullName ?? "SetChatNotificationSettingsAsync");

           try
           {
             return client.SetChatNotificationSettingsAsync(chatId, notificationSettings);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
